    /// Starts the sessions the macrostep's entries deferred (W3C SCXML 6.4), now that
    /// the macrostep is over.
    public func executePendingInvokes(engine: Engine<ABadInvokeArgumentIsReportedOncePolicy>) {
        SceRuntime.executePendingInvokes(&pendingInvokes) { pending in
            if pending.documentID.utf8.elementsEqual("inv1".utf8) {
                sceStartInvokeInv1(pending, engine: engine)
                return
            }
            if pending.documentID.utf8.elementsEqual("inv2".utf8) {
                sceStartInvokeInv2(pending, engine: engine)
                return
            }
            if pending.documentID.utf8.elementsEqual("inv3".utf8) {
                sceStartInvokeInv3(pending, engine: engine)
                return
            }
        }
    }

    /// Starts the session of `<invoke>` `inv1` (W3C SCXML 6.4).
    private func sceStartInvokeInv1(_ pending: PendingInvoke<ABadInvokeArgumentIsReportedOnceState>, engine: Engine<ABadInvokeArgumentIsReportedOncePolicy>) {
        // W3C SCXML C.1: the child is known by the id its parent mints for it and
        // keys the invocation on, so the sender of what it sends is the id it
        // publishes in `_ioprocessors`.
        let childSessionID = "\(sessionID).\(pending.invokeID)"
        let childPolicy = ABadInvokeArgumentIsReportedOnceSceSynthInvokeInv1Policy()
        // W3C SCXML 6.4.1: the child is handed the values this invoke names before it
        // initializes.
        var seeds: [String: LuaSeed] = [:]
        if let seedValue = evaluateSeed("v") {
            seeds["fromLoc"] = seedValue
        } else {
            raiseExecutionError("<invoke> <param name='fromLoc'> could not be read", engine: engine)
        }
        raiseExecutionError("<invoke> <param name='emptyLoc'> names no location", engine: engine)
        if let seedValue = evaluateSeed("obj.missing.deep") {
            seeds["broken"] = seedValue
        } else {
            raiseExecutionError("<invoke> <param name='broken'> could not be read", engine: engine)
        }
        if let seedValue = evaluateSeed("obj.missing.deep") {
            seeds["notInChild"] = seedValue
        } else {
            raiseExecutionError("<invoke> <param name='notInChild'> could not be read", engine: engine)
        }
        childPolicy.acceptSeeds(seeds)

        let session = InvokedSession(
            policy: childPolicy,
            sessionID: childSessionID,
            queue: ParentEventQueue(parentSessionID: sessionID)
        )
        // W3C SCXML 6.4.1: tracked before the child initializes.
        activeInvokes["inv1"] = ChildSession(
            sessionID: childSessionID,
            invokeID: "inv1",
            parentSessionID: sessionID,
            autoforward: false,
            finalizeScript: ""
        )
        // W3C SCXML 6.4: the child's delayed sends are measured on this machine's
        // clock, so a delay on either side of the boundary is the same instant and a
        // clock its host advances moves the child too.
        session.engine.setClock(engine.clock())
        // SCE_MESH.md §21.3: the child's router is the one the factory answers for this invoke
        // and this document (empty for a child written in line), installed before the child
        // initializes, since its first state may already send.
        engine.startChildMesh(of: session, invokeID: "inv1", document: documentStem("#a_bad_invoke_argument_is_reported_once__sce_synth_invoke__inv1"))
        session.initialize()
        sceInvokeChildInv1 = session
        // W3C SCXML 6.4: what the child sent while it initialized, and whether it
        // ended doing so.
        sceSettleInvokeInv1(engine: engine)
    }

    /// Takes what the session of `<invoke>` `inv1` sent this machine, and
    /// raises `done.invoke` once it has ended (W3C SCXML 5.5 + 6.3.1: with the donedata its
    /// top-level `<final>` stashed).
    private func sceSettleInvokeInv1(engine: Engine<ABadInvokeArgumentIsReportedOncePolicy>) {
        guard let child = sceInvokeChildInv1, !sceInvokeDoneInv1 else {
            return
        }
        drainAndRaiseChildEvents(
            childEngine: child,
            activeInvokes: activeInvokes,
            invokeKey: "inv1",
            engine: engine
        )
        if child.isInFinalState {
            sceInvokeDoneInv1 = true
            // SCE_MESH.md §21.5: the session reached its top-level `<final>`, so its router
            // is told once.
            child.detachMesh()
            raiseDoneInvoke(invokeID: "inv1", donedata: child.donedataAtFinal, engine: engine)
        }
    }

