    /// Exits one state (W3C SCXML 3.9): records its histories, runs its `<onexit>`,
    /// cancels its invocations and removes it from the configuration, in
    /// §scxml-D-exitStates's order.
    public func executeExitActions(_ state: ABadInvokeArgumentIsReportedOnceState, engine: Engine<ABadInvokeArgumentIsReportedOncePolicy>, configurationBeforeExit: [ABadInvokeArgumentIsReportedOnceState]) {
        // §scxml-D-exitStates orders one state's exit as onexit, then cancelInvoke,
        // then configuration.delete(s), so `In(s)` inside s's own handler is true:
        // the <onexit> switch comes first and the removal from the configuration
        // last.
        switch state {
        default:
            break  // No exit actions
        }
        // W3C SCXML 6.4: the invocations of an exited state end with it: one not yet
        // started never starts, and a running session is exited, its states' <onexit>
        // run, before it is dropped. What that exit sends to #_parent is dropped with
        // it (test252).
        switch state {
        case .s0:
            cancelInvokesForState(&pendingInvokes, .s0)
            sceInvokeChildInv1?.stop()
            sceInvokeChildInv1?.detachMesh()
            sceInvokeChildInv1 = nil
            activeInvokes["inv1"] = nil
            sceInvokeDoneInv1 = false
        case .s1:
            cancelInvokesForState(&pendingInvokes, .s1)
            sceInvokeChildInv2?.stop()
            sceInvokeChildInv2?.detachMesh()
            sceInvokeChildInv2 = nil
            activeInvokes["inv2"] = nil
            sceInvokeDoneInv2 = false
            sceInvokeChildInv3?.stop()
            sceInvokeChildInv3?.detachMesh()
            sceInvokeChildInv3 = nil
            activeInvokes["inv3"] = nil
            sceInvokeDoneInv3 = false
        default:
            break  // No invocations to cancel
        }
    }



    /// Appendix D selectTransitions, the half only this document can answer: the
    /// first of `state`'s own transitions, in document order, that `event` enables
    /// and whose guard holds. The engine walks the atomic states and their
    /// ancestors and keeps the ordered set; the null event asks for eventless
    /// transitions.
    public func firstEnabledTransition(
        _ state: ABadInvokeArgumentIsReportedOnceState,
        event: ABadInvokeArgumentIsReportedOnceEvent,
        engine: Engine<ABadInvokeArgumentIsReportedOncePolicy>
    ) -> EnabledTransition<ABadInvokeArgumentIsReportedOnceState>? {
        switch state {
        case .run:
            if event == .errorExecution {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 0,
                        hasActions: true,
                        isInternal: false
                    )
                }
            }
            if event == .childUp {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 1,
                        hasActions: true,
                        isInternal: false
                    )
                }
            }
            if event == .finish {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [.state(.done)],
                        transitionIndex: 2,
                        hasActions: false,
                        isInternal: false
                    )
                }
            }
        case .s0:
            if event == .childUp {
                // W3C SCXML 5.9: cond="_event.data.fromLoc === 7" lowered to Lua at build time, run by the engine
                if (evaluateGuard("(_event.data.fromLoc == 7)", engine: engine)) {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 0,
                        hasActions: true,
                        isInternal: false
                    )
                }
            }
            if event == .go {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [.state(.s1)],
                        transitionIndex: 1,
                        hasActions: false,
                        isInternal: false
                    )
                }
            }
        default:
            break
        }
        return nil
    }

    /// Runs one transition's executable content (W3C SCXML 3.13), between the
    /// microstep's exits and its entries.
